### 🛠️ Production Implementation & Technical Verification

1. **Root Cause Analysis & Architectural Design**:

`POST /api/messages` currently passes untrusted `req.body` directly into persistence. This allows malformed entities, blank or oversized chat content, absent participant IDs, and unexpected keys such as `__proto__` to enter the in-memory store.

The fix establishes a strict boundary at the HTTP controller:

- Zod validates the payload before `sendMessage` is invoked.
- `senderId` and `receiverId` must be non-blank strings.
- `content` must contain non-whitespace text and be at most 5,000 characters.
- `conversationId` is optional but, when present, must be non-blank.
- `.strict()` rejects unknown keys, including prototype-pollution-shaped payload fields.
- Validation failures return a stable `400` envelope and never call persistence.

2. **Production-Grade Implementation Source Code**:

### Production Source (`src/schemas/messageSchema.ts`)

```ts
import { z } from "zod";

const requiredIdentifier = z
  .string({
    required_error: "is required",
    invalid_type_error: "must be a string",
  })
  .trim()
  .min(1, "must not be empty");

export const createMessageSchema = z
  .object({
    senderId: requiredIdentifier,
    receiverId: requiredIdentifier,
    content: z
      .string({
        required_error: "is required",
        invalid_type_error: "must be a string",
      })
      .min(1, "must not be empty")
      .max(5000, "must not exceed 5000 characters")
      .refine((value) => value.trim().length > 0, {
        message: "must not be blank",
      }),
    conversationId: z
      .string({
        invalid_type_error: "must be a string",
      })
      .trim()
      .min(1, "must not be empty")
      .optional(),
  })
  .strict();

export type CreateMessageInput = z.infer<typeof createMessageSchema>;
```

### Production Source (`src/services/messageService.ts`)

```ts
import type { CreateMessageInput } from "../schemas/messageSchema";

export interface Message extends CreateMessageInput {
  id: string;
  createdAt: string;
}

const messages: Message[] = [];

export function sendMessage(input: CreateMessageInput): Message {
  const message: Message = {
    id: crypto.randomUUID(),
    ...input,
    createdAt: new Date().toISOString(),
  };

  messages.push(message);
  return message;
}

export function clearMessagesForTests(): void {
  messages.length = 0;
}
```

### Production Source (`src/controllers/messageController.ts`)

```ts
import type { Request, Response } from "express";
import { ZodError } from "zod";
import { createMessageSchema } from "../schemas/messageSchema";
import { sendMessage } from "../services/messageService";

function validationEnvelope(error: ZodError) {
  return {
    error: {
      code: "INVALID_MESSAGE_PAYLOAD",
      message: "Request body failed message creation validation.",
      details: error.issues.map((issue) => ({
        path: issue.path.join(".") || "body",
        message: issue.message,
        code: issue.code,
      })),
    },
  };
}

export function createMessage(req: Request, res: Response): Response {
  const parsed = createMessageSchema.safeParse(req.body);

  if (!parsed.success) {
    return res.status(400).json(validationEnvelope(parsed.error));
  }

  try {
    const message = sendMessage(parsed.data);
    return res.status(201).json({ data: message });
  } catch {
    return res.status(500).json({
      error: {
        code: "MESSAGE_PERSISTENCE_FAILED",
        message: "Unable to persist message.",
      },
    });
  }
}
```

### Production Source (`src/routes/messageRoutes.ts`)

```ts
import { Router } from "express";
import { createMessage } from "../controllers/messageController";

const messageRouter = Router();

messageRouter.post("/", createMessage);

export default messageRouter;
